const crypto = require('crypto');
const it = $input.first();
const roh = (it.json && it.json.body && typeof it.json.body === 'object') ? it.json.body : {};
const fehler = function (text) { return [{ json: { route: 'fehler', antwort: { ok: false, fehler: text } } }]; };
let p = null;
try { p = JSON.parse(String(roh.p || '{}')); } catch (x) { return fehler('Anfrage nicht lesbar.'); }
if (!p || typeof p !== 'object' || Array.isArray(p)) return fehler('Anfrage nicht lesbar.');
const aktion = String(p.aktion || '');
const ID_RE = /^doc_[0-9A-HJKMNP-TV-Z]{26}$/;
if (aktion === 'liste') return [{ json: { route: 'liste' } }];
if (aktion === 'detail' || aktion === 'analysieren') {
  if (!ID_RE.test(String(p.document_id || ''))) return fehler('Dokument-ID ungültig.');
  return [{ json: { route: aktion, document_id: p.document_id } }];
}
if (aktion === 'fall_setzen') {
  if (!ID_RE.test(String(p.document_id || ''))) return fehler('Dokument-ID ungültig.');
  const fs = String(p.fall || '');
  if (!/^[a-z][a-z_]{2,29}$/.test(fs)) return fehler('Fall ungültig.');
  return [{ json: { route: 'fall_setzen', document_id: p.document_id, fall: fs } }];
}
if (aktion === 'zuruecklegen') {
  if (!ID_RE.test(String(p.document_id || ''))) return fehler('Dokument-ID ungültig.');
  return [{ json: { route: 'zuruecklegen', document_id: p.document_id } }];
}
if (aktion === 'sparte_neu') {
  if (!/^[a-z][a-z0-9_]{2,63}$/.test(String(p.kategorie_key || ''))) return fehler('Bitte zuerst eine Kategorie wählen.');
  return [{ json: { route: 'sparte_neu', kategorie_key: p.kategorie_key, label: String(p.label || '').slice(0, 80) } }];
}
if (aktion === 'gliederung') {
  if (!/^[a-z][a-z0-9_]{2,63}$/.test(String(p.kategorie_key || ''))) return fehler('Bitte zuerst eine Kategorie wählen.');
  const g = String(p.schema || '');
  if (g !== 'jahr' && g !== 'sparte_jahr') return fehler('Gliederung ungültig.');
  return [{ json: { route: 'sparte_neu', kategorie_key: p.kategorie_key, label: String(p.label || '').slice(0, 80), gliederung: g } }];
}
if (aktion === 'aufgaben') {
  if (!ID_RE.test(String(p.document_id || ''))) return fehler('Dokument-ID ungültig.');
  return [{ json: { route: 'aufgaben', document_id: p.document_id } }];
}
if (aktion === 'aufgabe') {
  if (!ID_RE.test(String(p.document_id || ''))) return fehler('Dokument-ID ungültig.');
  const nr = Number(p.nr);
  if (!Number.isInteger(nr) || nr < 0 || nr > 14) return fehler('Empfehlung ungültig.');
  const f = String(p.faellig || '');
  if (f && !/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(f)) return fehler('Datum ungültig.');
  const seite = String(p.seite || '');
  if (!/^https:\/\/[a-z0-9.-]+\/webhook\/[a-z0-9-]{8,80}$/.test(seite)) return fehler('Seitenadresse ungültig. Bitte die Seite neu laden.');
  return [{ json: { route: 'aufgabe', document_id: p.document_id, nr: nr, faellig: f, seite: seite } }];
}
if (aktion === 'ablegen') {
  if (!ID_RE.test(String(p.document_id || ''))) return fehler('Dokument-ID ungültig.');
  const name = String(p.dateiname || '').trim();
  if (!/^[A-Za-z0-9][A-Za-z0-9._-]{3,149}$/.test(name) || name.indexOf('..') !== -1) return fehler('Dateiname ungültig. Erlaubt sind Buchstaben ohne Umlaute, Ziffern, Punkt, Bindestrich und Unterstrich, höchstens 150 Zeichen.');
  if (!/^[a-z][a-z0-9_]{2,63}$/.test(String(p.kategorie_key || ''))) return fehler('Bitte eine Kategorie wählen.');
  const sp = String(p.sparte_key || '');
  if (sp && !/^[a-z][a-z0-9_]{1,63}$/.test(sp)) return fehler('Sparte ungültig.');
  return [{ json: { route: 'ablegen', document_id: p.document_id, dateiname: name, kategorie_key: p.kategorie_key, sparte_key: sp, vertrag_ordner: String(p.vertrag_ordner || '').trim().slice(0, 80), auto: p.auto === true,
    person_key: /^[a-z][a-z_]{1,29}$/.test(String(p.person_key || '')) ? String(p.person_key) : '' } }];
}
// CR-13b+: Regeln von Rolf anlegen und deaktivieren (nur Vorschlagslogik, kein Löschen).
if (aktion === 'regel_neu') {
  const rtext = String(p.text || '').replace(/[<>]/g, '').replace(/\s+/g, ' ').trim();
  if (rtext.length < 5 || rtext.length > 300) return fehler('Die Regel muss zwischen 5 und 300 Zeichen lang sein.');
  const geltung = String(p.geltung || 'alle');
  if (['alle', 'kategorie', 'vorgang'].indexOf(geltung) === -1) return fehler('Geltungsbereich ungültig.');
  const rkat = geltung === 'kategorie' ? String(p.kategorie_key || '') : '';
  const rvg = geltung === 'vorgang' ? String(p.vorgang_key || '') : '';
  if (geltung === 'kategorie' && !/^[a-z][a-z0-9_]{2,63}$/.test(rkat)) return fehler('Kategorie ungültig.');
  if (geltung === 'vorgang' && !/^[a-z][a-z_]{2,39}$/.test(rvg)) return fehler('Vorgangsart ungültig.');
  const rdoc = String(p.document_id || '');
  return [{ json: { route: 'regel', op: 'neu', text: rtext, kat: rkat, vorgang: rvg, doc: ID_RE.test(rdoc) ? rdoc : '' } }];
}
if (aktion === 'regel_aus') {
  if (!/^rul_[0-9A-HJKMNP-TV-Z]{26}$/.test(String(p.rule_id || ''))) return fehler('Regel-ID ungültig.');
  return [{ json: { route: 'regel', op: 'aus', rule_id: p.rule_id } }];
}
if (aktion !== 'hochladen') return fehler('Unbekannte Aktion.');
const fall = String(p.fall || 'ablegen');
if (!/^[a-z][a-z_]{2,29}$/.test(fall)) return fehler('Fall ungültig.');
const bin = it.binary || {};
if (!bin.datei) return fehler('Keine Datei erhalten.');
const art = function (b) {
  if (b.length > 5 && b.slice(0, 5).toString('latin1') === '%PDF-') return 'application/pdf';
  if (b.length > 3 && b[0] === 255 && b[1] === 216 && b[2] === 255) return 'image/jpeg';
  if (b.length > 8 && b[0] === 137 && b.slice(1, 4).toString('latin1') === 'PNG') return 'image/png';
  return null;
};
const buf = await this.helpers.getBinaryDataBuffer(0, 'datei');
const mime = art(buf);
if (!mime) return fehler('Dateityp nicht erlaubt. Erlaubt sind PDF, JPG und PNG.');
if (mime === 'application/pdf' && buf.indexOf('/Encrypt') !== -1) return fehler('Das PDF ist passwortgeschützt oder verschlüsselt und kann nicht gelesen werden.');
let ki = buf;
let kiMime = mime;
if (mime !== 'application/pdf' && bin.ki_bild) {
  const kb = await this.helpers.getBinaryDataBuffer(0, 'ki_bild');
  const km = art(kb);
  if (km === 'image/jpeg' || km === 'image/png') { ki = kb; kiMime = km; }
}
const name = String(bin.datei.fileName || 'dokument').slice(0, 200);
return [{ json: { route: 'hochladen', fall: fall, original_filename: name, mime_type: mime, size_bytes: buf.length,
  content_hash: 'sha256:' + crypto.createHash('sha256').update(buf).digest('hex'),
  ki_mime: kiMime, ki_bytes: ki.length, ki_b64: ki.toString('base64') },
  binary: { datei: bin.datei } }];

// Kontextwerte aus jarvis_ops.context_document_settings (env-Verweise), Ablageregeln aus jarvis_privat.filing_rule / filing_subcategory, Ablageregister aus jarvis_privat.filing_target (CR-06).
const a = $('Anfrage pruefen').first();
const req = a.json;
if (req.route === 'fehler') return [{ json: req }];
const fehler = function (t) { return [{ json: { route: 'fehler', antwort: { ok: false, fehler: t } } }]; };
const z = $input.all().map(function (x) { return x.json; }).filter(function (r) { return r && r.context_id === 'privat'; })[0];
if (!z) return fehler('Kontexteinstellungen nicht lesbar.');
const regeln = Array.isArray(z.regeln) ? z.regeln : [];
const sparten = Array.isArray(z.sparten) ? z.sparten : [];
if (!regeln.length) return fehler('Ablageregeln nicht lesbar.');
const kat = {};
regeln.forEach(function (r) { kat[r.key] = { key: r.key, label: r.label, ordner: r.ordner, schema: r.schema, entschieden: r.entschieden === true, sparten: [] }; });
sparten.forEach(function (s) { if (kat[s.kat]) kat[s.kat].sparten.push({ key: s.key, label: s.label, ordner: s.ordner }); });
const auf = function (ref) {
  const m = /^env:([A-Z][A-Z0-9_]{3,63})$/.exec(String(ref || ''));
  if (!m) return null;
  let w = null;
  try { w = $vars[m[1]]; } catch (x) { w = null; }
  w = (typeof w === 'string') ? w.trim() : '';
  return /^[A-Za-z0-9_-]{10,200}$/.test(w) ? w : null;
};
let modell = '';
try { modell = $vars.JV_MODEL_REASONING; } catch (x) { modell = ''; }
modell = (typeof modell === 'string') ? modell.trim() : '';
const faelle = (Array.isArray(z.faelle) ? z.faelle : []).filter(function (f) { return f && /^[a-z][a-z_]{2,29}$/.test(String(f.key || '')); });
const fallMap = {};
faelle.forEach(function (f) { fallMap[f.key] = f; });
if ((req.route === 'hochladen' || req.route === 'fall_setzen') && !fallMap[req.fall]) return fehler('Unbekannter Fall. Bitte die Seite neu laden.');
// CR-13b+: Vorgangsarten mit Optionskatalog, aktive Regeln von Rolf, aktuelle Anschrift (zentrale Konfiguration, kein Hardcode).
const vorgaenge = (Array.isArray(z.vorgaenge) ? z.vorgaenge : []).filter(function (v) { return v && /^[a-z][a-z_]{2,39}$/.test(String(v.key || '')) && Array.isArray(v.optionen); })
  .map(function (v) { return { key: v.key, label: String(v.label || v.key), erkennung: String(v.erkennung || ''), optionen: v.optionen.filter(function (o) { return o && fallMap[o.fall]; }).map(function (o) { return { fall: o.fall, label: String(o.label || fallMap[o.fall].label), bedingung: o.bedingung || null, hinweis: o.hinweis || null, gruppe: o.gruppe || fallMap[o.fall].gruppe }; }) }; });
const handlungsregeln = (Array.isArray(z.handlungsregeln) ? z.handlungsregeln : []).filter(function (r) { return r && /^rul_[0-9A-HJKMNP-TV-Z]{26}$/.test(String(r.id || '')) && typeof r.text === 'string'; })
  .slice(0, 50).map(function (r) { return { id: r.id, text: r.text.slice(0, 300), kat: r.kat || null, vorgang: r.vorgang || null, seit: r.seit || null }; });
const pa = (z.privatadresse && typeof z.privatadresse === 'object') ? z.privatadresse : null;
const adresse = pa ? [pa.name, pa.strasse, [pa.plz, pa.ort].filter(function (x) { return x; }).join(' '), pa.land].filter(function (x) { return x && String(x).trim(); }).join(', ').slice(0, 200) : null;
// CR-15: betreute Personen (jarvis_privat.betreute_person, zentrale Konfiguration).
const personen = (Array.isArray(z.personen) ? z.personen : []).filter(function (p) { return p && /^[a-z][a-z_]{1,29}$/.test(String(p.key || '')); })
  .map(function (p) { return { key: p.key, name: String(p.name || p.key).slice(0, 80), ordner: (typeof p.ordner === 'string' && /^[A-Za-z0-9_-]{2,40}$/.test(p.ordner)) ? p.ordner : null,
    erkennung: Array.isArray(p.erkennung) ? p.erkennung.filter(function (x) { return typeof x === 'string' && x.trim().length >= 4; }).slice(0, 10) : [],
    todo: (typeof p.todo === 'string' && p.todo.trim().length >= 2) ? p.todo.trim().slice(0, 100) : null, selbst: p.selbst === true }; });
const personMap = {};
personen.forEach(function (p) { personMap[p.key] = p; });
const selbstP = personen.filter(function (p) { return p.selbst; })[0];
if (!selbstP) return fehler('Personenkonfiguration fehlt (betreute_person).');
const cfg = {
  context_id: 'privat',
  personen: personen, person: personMap, selbst_key: selbstP.key,
  vorgaenge: vorgaenge, handlungsregeln: handlungsregeln, adresse: adresse,
  faelle: faelle, fall: fallMap,
  inbox_id: auf(z.inbox_ref), archiv_id: auf(z.archive_root_ref), wurzel_id: auf(z.context_root_ref),
  kat: kat, kategorien: regeln.map(function (r) { return kat[r.key]; }),
  ziele: Array.isArray(z.ziele) ? z.ziele.filter(function (g) { return g && g.id && kat[g.kat]; }) : [],
  modell: /^[a-z0-9][a-z0-9.-]{2,80}$/.test(modell) ? modell : 'claude-sonnet-5',
  prompt_version: 's1-1.6.0',
  todo_liste: (typeof z.todo_list_name === 'string' && z.todo_list_name.trim().length >= 2) ? z.todo_list_name.trim().slice(0, 100) : null
};
if (!cfg.inbox_id || !cfg.archiv_id || !cfg.wurzel_id) return fehler('Ordnerkonfiguration unvollständig: Variable für Eingang, Archiv oder Wurzel fehlt.');
const aus = Object.assign({}, req, { cfg: cfg });
if (req.route !== 'hochladen') return [{ json: aus }];
const erlaubt = Array.isArray(z.allowed_mime_types) ? z.allowed_mime_types : [];
if (erlaubt.indexOf(req.mime_type) === -1) return fehler('Dateityp im Kontext nicht erlaubt.');
const grenze = Math.min(Number(z.max_file_size_mb) || 0, 15) * 1024 * 1024;
if (req.size_bytes > grenze) return fehler('Datei zu gross. Höchstens 15 MB.');
if (req.ki_mime !== 'application/pdf' && req.ki_bytes > 5 * 1024 * 1024) return fehler('Bild zu gross für die KI (höchstens 5 MB). Bitte über die Oberfläche hochladen, sie verkleinert Fotos automatisch.');
delete aus.ki_b64;
return [{ json: aus, binary: a.binary }];

const cfg = $('Konfiguration aufloesen').first().json.cfg;
const rows = $input.all().map(function (x) { return x.json; });
if (rows.some(function (r) { return r && r.error; })) return [{ json: { antwort: { ok: false, fehler: 'Liste konnte nicht gelesen werden.' } } }];
const ordner = function (p) { if (!p) return null; const t = String(p).split('/'); return t.length > 1 ? t.slice(0, -1).join('/') : p; };
const dokumente = rows.filter(function (r) { return r && r.document_id; }).map(function (r) {
  return { id: r.document_id, status: r.status, person_key: r.person_key || null, fall: r.fall || 'ablegen', dateiname: r.original_filename, eingang: r.received_at, kategorie_key: r.category_key,
