});
return [{ json: { antwort: { ok: true, dokumente: dokumente, kategorien: cfg.kategorien, faelle: cfg.faelle,
  regeln: cfg.handlungsregeln || [], personen: (cfg.personen || []).map(function (p) { return { key: p.key, name: p.name, ordner: p.ordner, selbst: p.selbst }; }), vorgaenge: (cfg.vorgaenge || []).map(function (v) { return { key: v.key, label: v.label }; }) } } }];

const dokOf = function (r) { const f = r.filing || {}; const q = f.anfrage || {};
  return { id: r.document_id, status: r.status, fall: r.fall || 'ablegen', dateiname_original: r.original_filename, eingang: r.received_at, kategorie_key: r.category_key, person_key: r.person_key || null,
    ablage: f.target_path || null, link: f.web_link || null, ablage_status: f.state || null,
    abgelegt_als: f.state === 'done' ? { kategorie_key: q.kategorie_key || r.category_key, sparte_key: q.sparte_key || null, vertrag_ordner: q.vertrag_ordner || null, dateiname: f.file_name || null } : null }; };
const regHinweis = function (g) { if (!g || !g.ziel) return null; const n = Number(g.anzahl); return 'Bestehende Ablage erkannt: ' + g.ziel + (n > 0 ? ' (' + n + (n === 1 ? ' Dokument' : ' Dokumente') + ')' : '') + '. Das Ziel ist unten vorausgewählt; zum Abweichen Kategorie oder Unterkategorie ändern.'; };
const rows = $input.all().map(function (x) { return x.json; }).filter(function (r) { return r && r.document_id; });
if (!rows.length) return [{ json: { antwort: { ok: false, fehler: 'Dokument nicht gefunden.' } } }];
const r = rows[0];
const an = r.analyse || null;
const v = an ? an.vorschlag : null;
const hw = (v && v.register && r.status !== 'filed') ? regHinweis(v.register) : null;
const antwort = { ok: true, dokument: dokOf(r), analyse: an ? an.ki : null, vorschlag: v, grund: an ? an.grund : null };
if (hw) antwort.hinweis = hw;
return [{ json: { antwort: antwort } }];

const dokOf = function (r) { const f = r.filing || {}; const q = f.anfrage || {};
  return { id: r.document_id, status: r.status, fall: r.fall || 'ablegen', dateiname_original: r.original_filename, eingang: r.received_at, kategorie_key: r.category_key,
