const crypto = require('crypto');
const k = $('Konfiguration aufloesen').first();
const alle = $input.all().map(function (x) { return x.json; });
if (alle.some(function (r) { return r && r.error; })) return [{ json: { weg: 'dublette', antwort: { ok: false, fehler: 'Datenbank nicht erreichbar. Bitte später erneut versuchen.' } } }];
const r = alle.filter(function (x) { return x && x.document_id; })[0];
const tag = function (v) { const m = /^([0-9]{4})-([0-9]{2})-([0-9]{2})/.exec(v ? new Date(v).toISOString() : ''); return m ? m[3] + '.' + m[2] + '.' + m[1] : ''; };
if (r && (r.analyse || r.status === 'filed' || r.status === 'planned')) {
