    dokument: dokOf(r), analyse: an ? an.ki : null, vorschlag: an ? an.vorschlag : null, grund: an ? an.grund : null } } }];
}
if (r) return [{ json: Object.assign({}, k.json, { weg: 'analyse', document_id: r.document_id, received_at: new Date(r.received_at).toISOString().replace(/[.][0-9]{3}Z$/, 'Z'), erneut: true }) }];
const B32 = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
let t = Date.now();
let id = '';
for (let i = 0; i < 10; i++) { id = B32[t % 32] + id; t = Math.floor(t / 32); }
const zz = crypto.randomBytes(16);
for (let i = 0; i < 16; i++) { id += B32[zz[i] % 32]; }
return [{ json: Object.assign({}, k.json, { weg: 'neu', document_id: 'doc_' + id, source_event_id: 'evt_web_' + id, received_at: new Date().toISOString().replace(/[.][0-9]{3}Z$/, 'Z'), erneut: false }), binary: k.binary }];

const a = $('Anfrage pruefen').first().json;
