return [{ json: { ki_b64: a.ki_b64, ctx: { document_id: d.document_id, received_at: d.received_at, original_filename: a.original_filename, mime_type: a.mime_type, ki_mime: a.ki_mime, erneut: !!d.erneut, filing: null, fall: a.fall || 'ablegen' } } }];

const dokOf = function (r) { const f = r.filing || {}; const q = f.anfrage || {};
