    ablage: f.target_path || null, link: f.web_link || null, ablage_status: f.state || null,
    abgelegt_als: f.state === 'done' ? { kategorie_key: q.kategorie_key || r.category_key, sparte_key: q.sparte_key || null, vertrag_ordner: q.vertrag_ordner || null, dateiname: f.file_name || null } : null }; };
const crypto = require('crypto');
const k = $('Konfiguration aufloesen').first().json;
const cfg = k.cfg;
const rows = $input.all().map(function (x) { return x.json; });
const nein = function (t) { return [{ json: { weiter: false, antwort: { ok: false, fehler: t } } }]; };
if (rows.some(function (r) { return r && r.error; })) return nein('Datenbank nicht erreichbar.');
const r = rows.filter(function (x) { return x && x.document_id; })[0];
if (!r) return nein('Dokument nicht gefunden.');
const f = r.filing || {};
const an = r.analyse || null;
const form = function (extra) { return Object.assign({ ok: true, dokument: dokOf(r), analyse: an ? an.ki : null, vorschlag: an ? an.vorschlag : null, grund: an ? an.grund : null }, extra); };
const alt = f.started_at ? (Date.now() - new Date(f.started_at).getTime() > 10 * 60 * 1000) : false;
const frei = ['understood', 'needs_review', 'filed'].indexOf(r.status) !== -1 || (r.status === 'planned' && (f.state === 'inconclusive' || (f.state === 'running' && alt)
  || (f.state === 'reverting' && f.revert_started_at && (Date.now() - new Date(f.revert_started_at).getTime() > 10 * 60 * 1000))));
if (!frei) return nein(r.status === 'planned' ? 'Die Ablage läuft bereits. Bitte in einer Minute die Liste aktualisieren.' : 'Das Dokument kann im Status „' + r.status + '“ nicht abgelegt werden.');
if (!an) return nein('Keine Analyse vorhanden. Bitte „Analyse wiederholen“ klicken.');
// CR-09a A2/A10: Sofortablage nur für Altbestand, nur mit dem gespeicherten Vorschlag, nicht nach einem Rückgängig.
const av = an.vorschlag || {};
const autoWunsch = k.auto === true;
